  "requirement_items": [
    {
      "section": "4.2.3.7",
      "label": "[REQ-1-OAD-1590]",
      "text": "Areas on the telescope or enclosure where personnel need to work frequently at a height more than 1.8 meters above the observing floor shall be provided with at least two paths of egress not requiring the use of elevators, in case fire or some other emergency blocks one escape route.",
      "id": "REQ-1-OAD-1590"
    },
    {
      "section": "4.2.3.7",
      "label": "[REQ-1-OAD-1605]",
      "text": "Components of the observatory wide fire system shall be mounted on the telescope structure to:\n� allow personnel in this area to initiate a fire alarm\n� ensure fire alarms are audible and visible to personnel working on the telescope structure\n� detect smoke and heat caused by a fire on the telescope or telescope.",
      "id": "REQ-1-OAD-1605"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1610]",
      "text": "The M1 segment handling system (M1 SHS) is an integrated system that consists of: (1) a Segment Lifting Fixture (SLF) that interfaces to the Mounted Segment Assembly (MSA); (2) a positioning system that moves the SLF to install or remove the segments in the primary mirror array; and (3) a crane or other means to raise segments from the observing floor to the mirror cell and lower them back to the observing floor.",
      "id": "REQ-1-OAD-1610"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1612]",
      "text": "The M1 SHS shall be mounted on the telescope structure.",
      "id": "REQ-1-OAD-1612"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1614]",
      "text": "Installation and removal of primary mirror segments shall be accomplished with the telescope locked in a zenith-pointing orientation.",
      "id": "REQ-1-OAD-1614"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1616]",
      "text": "The M1 SHS shall enable the installation and removal of any 10 primary mirror segments per 10-hour day.",
      "id": "REQ-1-OAD-1616"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1618]",
      "text": "The M1 SHS duty cycle includes 2000 installation or removal operations during construction, 10 routine segment exchanges during a single 8 hour day, once every two weeks for fifty years (13,000 segment exchanges), and a proof test (at two times rated load) every six months for 50 years.",
      "id": "REQ-1-OAD-1618"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1620]",
      "text": "The M1 SHS shall be able to access, install and remove any of the 492 segments in the primary mirror.",
      "id": "REQ-1-OAD-1620"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1622]",
      "text": "The M1 SHS shall be placed in a stowed position when the telescope is used for observing. In its stowed position, no component of the M1 SHS shall vignette the field of view of any of the science instruments.",
      "id": "REQ-1-OAD-1622"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1624]",
      "text": "In its stowed position, the M1 SHS shall not increase the obscuration of the telescope aperture by more than 2 square meters, evaluated for any point in a telescope field of view of 30 arcseconds radius.",
      "id": "REQ-1-OAD-1624"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1626]",
      "text": "Any increase in obscuration of the telescope aperture by the stowed M1 SHS shall have a simple geometry that can be easily masked in an instrument pupil plane, and should avoid obscuring the edges of segments as viewed by the alignment and phasing system.",
      "id": "REQ-1-OAD-1626"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1628]",
      "text": "In its stowed position, the M1 SHS shall not produce any acoustic noise or structural vibration when the telescope zenith angle varies from -1 to 90 degrees.",
      "id": "REQ-1-OAD-1628"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1630]",
      "text": "The M1 SHS shall enable MSAs to be raised and lowered directly to a segment handling cart on the observatory floor.",
      "id": "REQ-1-OAD-1630"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1632]",
      "text": "The M1 SHS shall have six motorized degrees of freedom (Tx, Ty, Tz, Rx, Ry, Rz, defined in a convenient orthogonal coordinate system).",
      "id": "REQ-1-OAD-1632"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1634]",
      "text": "The M1 SHS shall level the segment (Tip = Tilt = 0) prior to installing/removing the segment onto the handling cart.",
      "id": "REQ-1-OAD-1634"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1636]",
      "text": "If the M1 SHS is stowed when an earthquake up to the level of a very infrequent earthquake occurs, the M1 SHS shall not damage any telescope mirror or any science instrument.",
      "id": "REQ-1-OAD-1636"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1638]",
      "text": "If the M1 SHS is in use when an earthquake, up to the level of an infrequent earthquake occurs, the M1 SHS shall not damage any telescope mirror systems, including M1 and M3, or any science instrument.",
      "id": "REQ-1-OAD-1638"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1639]",
      "text": "If the M1 SHS is raising or lowering a segment from/to the observing floor when an earthquake up to the level of a frequent earthquake occurs, the M1 SHS shall not allow damage to the MSA being moved.",
      "id": "REQ-1-OAD-1639"
    },
    {
      "section": "4.2.3.8",
      "label": "[REQ-1-OAD-1640]",
      "text": "The M1 SHS shall strictly minimize any contaminants which might be deposited onto the surface of the primary mirror or tertiary mirror, including dust, debris or oil or other fluids.",
      "id": "REQ-1-OAD-1640"
    }
  ],
